  project_id INTEGER,
  outcome_code VARCHAR(10),
  outcome_details VARCHAR(255),
  FOREIGN KEY (outcome_code) REFERENCES Research_Outcomes(outcome_code),
  FOREIGN KEY (project_id) REFERENCES Projects(project_id)
);

